+.station{background:var(--ink);color:var(--cream);margin:0 calc(50% - 50vw);padding:58px max(16px,calc((100vw - 1100px)/2))}.station-head{display:flex;justify-content:space-between;align-items:end;gap:20px;margin-bottom:32px}.counter{font:600 3rem "Fraunces";color:var(--gold)}.counter small{display:block;font:9px "DM Mono";color:var(--cream);letter-spacing:.12em;text-transform:uppercase}.workbench{display:grid;grid-template-columns:.8fr 1.2fr;gap:26px}.card{min-height:292px;background:var(--cream);color:var(--ink);border:3px solid var(--gold);box-shadow:10px 10px 0 var(--red);padding:28px;display:flex;flex-direction:column;justify-content:space-between;position:relative;animation:deal .4s both}@keyframes deal{from{opacity:0;transform:translateX(-25px) rotate(-2deg)}}.card:after{content:attr(data-no);position:absolute;right:18px;top:8px;font:600 4rem "Fraunces";color:#e7d7b5}.glyph{font-size:2.2rem;margin-bottom:22px}.card h3{font-size:clamp(1.8rem,4vw,2.6rem);line-height:1.05;margin:0;max-width:10ch}.card p{font-size:10px;line-height:1.6;color:#687063}.bins{display:grid;grid-template-columns:1fr 1fr;gap:12px}.bin{min-height:130px;border:1px solid #fff9e866;background:transparent;color:var(--cream);font:inherit;text-align:left;padding:20px;cursor:pointer;display:flex;flex-direction:column;justify-content:space-between;transition:.2s}.bin:hover,.bin:focus-visible{outline:0;border-color:var(--gold);background:#d8a12f1f;transform:translateY(-3px)}.bin span{font-size:8px;letter-spacing:.11em;text-transform:uppercase;opacity:.7}.bin strong{font:600 1.2rem "Fraunces"}.bin b{color:var(--gold);font-size:1.3rem}.bin.flash{animation:flash .5s}@keyframes flash{50%{background:var(--gold);color:var(--ink)}}.meter{margin-top:28px;border-top:1px solid #fff9e84d;padding-top:23px;display:grid;grid-template-columns:160px 1fr;align-items:center;font-size:9px;letter-spacing:.1em;text-transform:uppercase}.track{height:3px;background:#fff9e833}.track i{display:block;height:3px;width:calc