+.reflect{padding:72px 0;display:grid;grid-template-columns:1fr 1fr;gap:46px}.reflect blockquote{font:600 clamp(1.8rem,4vw,3.7rem)/1.08 "Fraunces";letter-spacing:-.035em;margin:0}.reflect em{color:var(--red)}.prompt{border-left:1px solid;padding-left:30px}.prompt label{display:block;font-size:9px;letter-spacing:.12em;text-transform:uppercase;margin-bottom:14px}textarea{width:100%;min-height:130px;border:0;border-bottom:3px solid;background:#fff6;font:600 1.05rem/1.6 "Fraunces";padding:13px;color:var(--ink);resize:vertical}textarea:focus{outline:2px solid var(--gold)}button.seal{margin-top:17px;border:0;background:var(--red);color:var(--cream);padding:16px 20px;font:500 10px "DM Mono";letter-spacing:.1em;text-transform:uppercase;box-shadow:5px 5px var(--ink);cursor:pointer}.receipt{display:none;background:var(--cream);border:1px solid;padding:36px;max-width:720px;margin:0 auto 72px;box-shadow:0 18px 40px #26302b35}.receipt.show{display:block;animation:rise .5s}@keyframes rise{from{opacity:0;transform:translateY(20px)}}.receipt h2{font-size:2.5rem;margin:0}.chosen{font:600 1.35rem/1.5 "Fraunces";margin:22px 0}.receipt small{color:#687063}footer{border-top:1px solid #17382e66;padding:28px 0 48px;display:flex;justify-content:space-between;gap:20px;font-size:9px;line-height:1.7}.source{max-width:580px}.source a{color:var(--red);font-weight:bold}
